PROBE = '"""One-shot, GET-only W-API diagnostic. Never prints credentials or message data."""\nimport hashlib\nimport json\nimport os\nimport re\nimport shlex\nimport socket\nimport subprocess\nfrom pathlib import Path\nfrom urllib.error import HTTPError\nfrom urllib.parse import urlencode\nfrom urllib.request import Request, HTTPRedirectHandler, build_opener\n\nKEYS = {\'WAPI_INSTANCE_ID\', \'WAPI_API_TOKEN\', \'WAPI_TOKEN\'}\nUNITS = (\'santana-mcp-lab.service\', \'santana-mcp-lab-tunnel.service\',\n         \'openbot-tunnel.service\', \'docker.service\', \'sana-lab-bridge.service\')\nROUTES = {\'connection\': \'/v1/instance/status-instance\',\n          \'instance\': \'/v1/instance/fetch-instance\',\n          \'chats\': \'/v1/chats/fetch-chats\',\n          \'contacts\': \'/v1/contacts/fetch-contacts\'}\n\n\ndef command(args):\n    p = subprocess.run(args, capture_output=True, text=True, timeout=10)\n    return p.returncode, p.stdout\n\n\ndef services():\n    result = {}\n    for unit in UNITS:\n        rc, out = command([\'systemctl\', \'show\', unit, \'-p\', \'MainPID\', \'-p\', \'ActiveState\',\n                           \'-p\', \'WorkingDirectory\', \'-p\', \'EnvironmentFiles\'])\n        result[unit] = dict(x.split(\'=\', 1) for x in out.splitlines() if \'=\' in x)\n    return result\n\n\ndef parse_env_file(path):\n    result = {}\n    # Parse assignments as data; never source a shell file or execute expansions.\n    for line in Path(path).read_text().splitlines():\n        m = re.match(r\'^\\s*(?:export\\s+)?([A-Z][A-Z0-9_]*)=(.*)$\', line)\n        if not m or m[1] not in KEYS:\n            continue\n        parts = shlex.split(m[2], comments=True)\n        if len(parts) == 1:\n            result[m[1]] = parts[0]\n    return result\n\n\nclass NoRedirect(HTTPRedirectHandler):\n    def redirect_request(self, *args, **kwargs):\n        return None\n\n\ndef project(label, http, payload):\n    """Allowlisted evidence only. HTTP 200 error envelopes are not success."""\n    entry = {\'operation\': label, \'http\': http, \'ok\': False}\n    if not isinstance(payload, (dict, list)):\n        return {**entry, \'result\': \'INVALID_PAYLOAD\'}\n    if isinstance(payload, dict):\n        failed = payload.get(\'error\') not in (None, False, \'\') or payload.get(\'success\') is False\n        texts = \' \'.join(str(payload.get(k, \'\')) for k in (\'error\', \'message\', \'status\')).lower()\n        if http == 200 and not failed:\n            entry[\'ok\'] = True\n        if \'pro\' in texts and any(x in texts for x in (\'lite\', \'plano\', \'plan\', \'exclusive\', \'exclusiv\')):\n            entry[\'result\'] = \'PLAN_RESTRICTED\'\n        elif http in (401, 403):\n            entry[\'result\'] = \'AUTH_OR_ACCESS_DENIED\'\n        elif http == 429:\n            entry[\'result\'] = \'RATE_LIMITED\'\n        elif not entry[\'ok\']:\n            entry[\'result\'] = \'API_ERROR\'\n        inner = payload.get(\'data\') if isinstance(payload.get(\'data\'), dict) else payload\n        if label == \'connection\':\n            connected = inner.get(\'connected\')\n            if not isinstance(connected, bool):\n                entry[\'ok\'] = False\n                entry[\'result\'] = \'CONNECTION_SHAPE_UNVERIFIED\'\n            else:\n                entry[\'connected\'] = connected\n        if label == \'instance\':\n            for k in (\'type\', \'instanceType\', \'plan\', \'planType\'):\n                if str(inner.get(k, \'\')).upper() in (\'LITE\', \'PRO\'):\n                    entry[\'instance_type\'] = str(inner[k]).upper()\n        if label in (\'chats\', \'contacts\'):\n            for k in (label, \'items\', \'data\'):\n                if isinstance(payload.get(k), list):\n                    entry[\'sample_count\'] = len(payload[k])\n                    break\n    else:\n        entry[\'ok\'] = http == 200\n        entry[\'sample_count\'] = len(payload)\n    return entry\n\n\ndef probe(credentials):\n    instance = credentials.get(\'WAPI_INSTANCE_ID\', \'\')\n    token = credentials.get(\'WAPI_API_TOKEN\') or credentials.get(\'WAPI_TOKEN\', \'\')\n    if not re.fullmatch(r\'[A-Za-z0-9_-]{1,80}\', instance) or not token:\n        return {\'status\': \'CREDENTIALS_UNAVAILABLE\', \'calls\': []}\n    calls = []\n    for label, path in ROUTES.items():\n        params = {\'instanceId\': instance}\n        if label in (\'chats\', \'contacts\'):\n            params.update(perPage=1, page=1)\n        request = Request(\'https://api.w-api.app\' + path + \'?\' + urlencode(params),\n                          headers={\'Authorization\': \'Bearer \' + token, \'Accept\': \'application/json\'}, method=\'GET\')\n        try:\n            try:\n                response = build_opener(NoRedirect()).open(request, timeout=8)\n            except HTTPError as e:\n                response = e\n            with response:\n                raw = response.read(1_000_001)\n                status = response.code\n            payload = json.loads(raw) if len(raw) <= 1_000_000 else None\n            entry = project(label, status, payload)\n        except Exception:\n            entry = {\'operation\': label, \'http\': None, \'ok\': False, \'result\': \'REDACTED_TRANSPORT_ERROR\'}\n        calls.append(entry)\n        if entry.get(\'http\') in (401, 429):\n            break\n    return {\'status\': \'PROBED_READ_ONLY\', \'calls\': calls}\n\n\ndef main():\n    if socket.gethostname().split(\'.\')[0] != \'srv1849463\':\n        return {\'status\': \'WRONG_HOST\'}\n    before = services()\n    report = {\'uid\': os.geteuid(), \'host_verified\': True, \'sources\': [], \'real_send_attempts\': 0,\n              \'production_writes\': 0, \'services_before\': {u: {k: v for k, v in d.items()\n              if k in (\'MainPID\', \'ActiveState\')} for u, d in before.items()}}\n    candidates = [(\'invocation_environment\', {k: v for k, v in os.environ.items() if k in KEYS})]\n    for unit in (\'santana-mcp-lab.service\', \'sana-lab-bridge.service\'):\n        props = before.get(unit, {})\n        pid = props.get(\'MainPID\', \'0\')\n        try:\n            data = dict(x.split(\'=\', 1) for x in Path(\'/proc\', pid, \'environ\').read_bytes().decode().split(\'\\0\') if \'=\' in x)\n            candidates.append((unit + \':process\', {k: v for k, v in data.items() if k in KEYS}))\n            if unit == \'santana-mcp-lab.service\':\n                report[\'lab\'] = {\'source\': data.get(\'SANTANA_DATA_SOURCE\'),\n                    \'send_disabled\': data.get(\'SANTANA_SEND_ENABLED\', \'false\').lower() == \'false\'\n                    and data.get(\'SANTANA_SEND_MODE\', \'disabled\') == \'disabled\',\n                    \'oauth_forwarding\': data.get(\'SANA_READ_FORWARD_BEARER\') == \'true\'}\n                cwd = Path(props[\'WorkingDirectory\'])\n                report[\'lab\'][\'server_sha256\'] = hashlib.sha256((cwd / \'server.py\').read_bytes()).hexdigest()\n        except (OSError, ValueError, KeyError):\n            report[\'sources\'].append({\'source\': unit + \':process\', \'accessible\': False})\n        for path in re.findall(r\'(\\S+)\\s+\\(ignore_errors=\', props.get(\'EnvironmentFiles\', \'\')):\n            try:\n                candidates.append((unit + \':configured_env_file\', parse_env_file(path)))\n            except (OSError, ValueError):\n                report[\'sources\'].append({\'source\': unit + \':configured_env_file\', \'accessible\': False})\n    # Only existing Sana bridge container, no enumeration of unrelated secrets.\n    rc, raw = command([\'docker\', \'inspect\', \'--format\', \'{{json .Config.Env}}\', \'sana-lab-bridge\'])\n    if rc == 0:\n        try:\n            pairs = dict(x.split(\'=\', 1) for x in json.loads(raw) if \'=\' in x)\n            candidates.append((\'sana-lab-bridge:container_environment\', {k: v for k, v in pairs.items() if k in KEYS}))\n        except (ValueError, TypeError):\n            pass\n    else:\n        report[\'sources\'].append({\'source\': \'sana-lab-bridge:container_environment\', \'accessible\': False})\n    selected = None\n    for label, env in candidates:\n        complete = bool(env.get(\'WAPI_INSTANCE_ID\') and (env.get(\'WAPI_API_TOKEN\') or env.get(\'WAPI_TOKEN\')))\n        report[\'sources\'].append({\'source\': label, \'accessible\': True, \'complete_wapi_credentials\': complete})\n        if complete and selected is None:\n            selected = env\n    report[\'wapi\'] = probe(selected or {})\n    after = services()\n    report[\'service_pids_unchanged\'] = all(before[u].get(\'MainPID\') == after[u].get(\'MainPID\') for u in UNITS)\n    return report\n\n\nif __name__ == \'__main__\':\n    try:\n        print(json.dumps(main(), ensure_ascii=False, indent=2))\n    except Exception:\n        print(json.dumps({\'status\': \'REDACTED_DIAGNOSTIC_FAILURE\', \'real_send_attempts\': 0, \'production_writes\': 0}))\n'
BASE_HASH = '63a85c509957532a8091f0ad13b5a5423a0dfeb19a007310bac1f0943f27b6ee'
BASE_ARCHIVE = Path('/home/runner/santana-mcp-staging/63a85c509957532a/WhatsApp-Santana-MCP-v5-Consolidado.zip')

def execute():
    if os.geteuid()!=0 or socket.gethostname().split('.')[0]!='srv1849463':
        raise RuntimeError('Execute como root somente em srv1849463; nada alterado.')
    fd=os.open(BASE_ARCHIVE,os.O_RDONLY|os.O_NOFOLLOW)
    with os.fdopen(fd,'rb') as f: blob=f.read(2097153)
    if hashlib.sha256(blob).hexdigest()!=BASE_HASH:
        raise RuntimeError('ZIP base divergente; nada alterado.')
    directory=Path(tempfile.mkdtemp(prefix='santana-wapi-readonly-',dir='/root'))
    with zipfile.ZipFile(io.BytesIO(blob)) as z:
        validator=z.read('whatsapp-santana-mcp/archive_safety.py')
    scope={};exec(compile(validator,'verified_archive_safety','exec'),scope)
    scope['extract_verified'](blob,BASE_HASH,directory)
    source=directory/'whatsapp-santana-mcp'
    sys.path.insert(0,str(source))
    import install
    target=install.discover()
    for name,expected in BASELINE.items():
        p=target['root']/name
        if p.is_symlink() or not p.is_file():
            raise RuntimeError('Arquivo ativo inseguro; nada alterado.')
        digest=hashlib.sha256(p.read_bytes()).hexdigest()
        accepted={expected}
        if name in PATCHES: accepted.add(hashlib.sha256(PATCHES[name].encode()).hexdigest())
        if digest not in accepted:
            raise RuntimeError('Código ativo mudou desde a auditoria; nada alterado.')
    for name,content in PATCHES.items():
        path=source/name;path.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
        path.write_text(content);os.chmod(path,0o600)
    clean={k:os.environ[k] for k in ('PATH','HOME','LANG') if k in os.environ}
    print('Verificado. Testando e atualizando somente o LAB, sem trocar provider ou credenciais.',flush=True)
    applied=subprocess.run([sys.executable,str(source/'install.py'),'--apply'],cwd=source,
                           env=clean,capture_output=True,text=True,timeout=180)
    if applied.returncode:
        print(applied.stdout[-2000:])
        raise RuntimeError('Instalação não confirmada; verifique a mensagem de reversão acima.')
    installed=json.loads(applied.stdout)
    namespace={'__name__':'santana_readonly_probe'}
    exec(compile(PROBE,'audited_readonly_probe','exec'),namespace)
    diagnosis=namespace['main']()
    report={'status':'PATCH_INSTALLED_REAL_INTEGRATION_PENDING','installation':installed,
            'diagnosis':diagnosis,'authorized_read':{'proven':False,
            'reason':'individual_real_read_binding_not_established'},
            'real_messages_sent':0,'production_writes':0,
            'rollback_command':['python3',str(source/'rollback.py'),installed['backup']]}
    stage=BASE_ARCHIVE.parent
    name='wapi-root-result-'+str(time.time_ns())+'.json'
    dfd=os.open(stage,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try:
        fd=os.open(name,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o644,dir_fd=dfd)
        with os.fdopen(fd,'w') as f:json.dump(report,f,ensure_ascii=False,indent=2)
    finally:os.close(dfd)
    print(json.dumps(report,ensure_ascii=False,indent=2))
    print('Relatório disponível para coleta remota:',name)

if __name__=='__main__':
    try:execute()
    except Exception as exc:
        print('PAREI:',str(exc));raise SystemExit(1)
